# -*- coding: utf-8 -*-
# N1 5 chu + 7 tou + 5 tan
P1 = "Pahami argumen utama penulis: biasanya di kalimat penutup atau setelah しかし/とはいえ/むしろ."
P2 = "Soal alasan/指示語: baca kalimat sebelum dan sesudah bagian bergaris bawah; jawaban hampir selalu di sana."
P3 = "Pilihan yang memutlakkan (すべて・必ず・全く) atau memuat hal di luar teks hampir pasti salah."
PT = "Soal 統合: tandai pendapat A dan B secara terpisah, lalu cari titik temu/perbedaannya."
JN = 'Teks menengah (内容理解・中文)'; JT = 'Bacaan gabungan (統合理解)'; JS = 'Teks pendek (内容理解・短文)'
R = ['Tidak disebut dalam teks.', 'Berlawanan dengan isi teks.', 'Berlebihan / bukan argumen penulis.']
def C(jp, id, qs):
    return dict(slot='chu', jenis=JN, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, [P2, P3, P1][i % 3]) for i, (q, ok, w, al, bu) in enumerate(qs)])
def X(jp, id, qs):
    return dict(slot='tou', jenis=JT, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, PT) for (q, ok, w, al, bu) in qs])
def T(jp, id, q, ok, w, al, bu):
    return dict(slot='tan', jenis=JS, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, P1)])
B = [
 C('「うそも方便」という言葉があるように、人間関係においては、真実をそのまま告げることが常に最善とは限らない。病気の友人に、あえて回復の見込みが薄いことを伝えない場合などがその例だろう。\n　だが、善意からつく嘘にも限界がある。嘘が発覚したとき、相手は「自分は信頼されていなかった」と感じ、かえって深く傷つく恐れがあるからだ。また、嘘を重ねるうちに、つく側自身も後ろめたさを抱え込むことになる。\n　重要なのは、真実を隠すか明かすかの二択で考えるのではなく、真実を、相手が受け止められる形と時期を見極めて伝える方法を探ることだろう。誠実さとは、事実をただ突きつけることでも、隠すことでもなく、相手への思いやりを込めて向き合う態度のことなのである。',
   'Seperti ungkapan "bohong demi kebaikan", dalam hubungan antarmanusia menyampaikan kebenaran apa adanya belum tentu selalu terbaik. Contohnya sengaja tak memberi tahu teman yang sakit bahwa harapan sembuh tipis.\n Namun kebohongan yang lahir dari niat baik pun ada batasnya. Sebab saat kebohongan ketahuan, lawan merasa "saya tak dipercaya" dan malah terluka lebih dalam. Dan sambil menumpuk kebohongan, pihak yang berbohong pun memikul rasa bersalah.\n Yang penting bukan memikirkan dua pilihan menyembunyikan atau mengungkap kebenaran, tetapi mencari cara menyampaikan kebenaran dengan bentuk dan waktu yang bisa diterima lawan. Ketulusan bukan sekadar menyodorkan fakta atau menyembunyikannya, melainkan sikap menghadapi dengan kepedulian pada lawan.',
   [('筆者が 「善意の 嘘」の 問題と して 述べて いる ことは 何か。', '発覚すると 相手が 信頼されて いなかったと 感じ 傷つく こと', ['嘘は すぐに 忘れられる こと', '相手が 喜ぶ こと', '嘘を つく 側は 気楽な こと'], 'Masalah kebohongan baik.', '相手は「自分は信頼されていなかった」と感じ、かえって深く傷つく'),
    ('「真実を 隠すか 明かすかの 二択」に 対して、筆者は どう すべきだと 述べて いるか。', '相手が 受け止められる 形と 時期を 見極めて 伝える', ['常に 明かす', '常に 隠す', '第三者に 任せる'], 'Alternatif penulis.', '相手が受け止められる形と時期を見極めて伝える'),
    ('筆者の 考える 誠実さと は 何か。', '思いやりを 込めて 相手に 向き合う 態度', ['事実を ただ 突きつける こと', '事実を 隠し 通す こと', '嘘を つかない こと だけ'], 'Definisi.', '相手への思いやりを込めて向き合う態度')]),
 C('近年、AI翻訳の精度は飛躍的に向上し、外国語の学習は不要になるという声もある。確かに、旅行や簡単な仕事のやり取りには、機械の翻訳で十分に事足りる場面が増えた。\n　しかし、言語は単なる情報の置き換えではない。ある言葉に込められたニュアンスや、その社会の価値観、さらには話し手の人柄まで、機械が完全に訳し切ることは難しい。また、外国語を学ぶ過程で、自分の母語や自国の文化を相対的に見る視点が養われることも見逃せない。\n　機械を使いこなすことと、外国語を学ぶことは対立しない。翻訳の結果を正しく判断するためにも、一定の語学力は、むしろこれまで以上に必要とされるのではないか。',
   'Belakangan akurasi terjemahan AI meningkat pesat dan ada pendapat belajar bahasa asing jadi tak perlu. Memang untuk perjalanan atau urusan kerja sederhana, makin banyak situasi yang cukup dengan terjemahan mesin.\n Namun bahasa bukan sekadar pertukaran informasi. Nuansa yang dikandung kata, nilai masyarakatnya, bahkan watak pembicara sulit diterjemahkan tuntas oleh mesin. Juga tak boleh dilewatkan bahwa dalam proses belajar bahasa asing terlatih sudut pandang melihat bahasa ibu dan budaya sendiri secara relatif.\n Menguasai mesin dan belajar bahasa asing tak bertentangan. Bahkan untuk menilai hasil terjemahan dengan benar, bukankah kemampuan bahasa tertentu justru lebih dibutuhkan dari sebelumnya?',
   [('AI翻訳に ついて、筆者が 認めて いる ことは 何か。', '簡単な 場面では 機械の 翻訳で 十分な ことが 増えた', ['翻訳の 精度は 低い', '機械は ニュアンスも 完全に 訳せる', '旅行では 使えない'], 'Pengakuan.', '機械の翻訳で十分に事足りる場面が増えた'),
    ('外国語を 学ぶ 利点と して 筆者が 述べて いる ことは 何か。', '母語や 自国の 文化を 相対的に 見る 視点が 養われる こと', ['翻訳の 費用が 減る こと', '機械を 使わなくて 済む こと', '話す 速度が 上がる こと'], 'Manfaat belajar.', '母語や自国の文化を相対的に見る視点が養われる'),
    ('筆者の 主張は どれか。', '翻訳結果を 判断する ために、語学力は これからも 必要だ', ['外国語学習は 不要に なった', '機械翻訳を 使う べきでは ない', '語学力は 機械に 任せる べきだ'], 'Kalimat akhir.', '翻訳の結果を正しく判断するためにも、一定の語学力は必要')]),
 C('日本では、年功序列の賃金体系が長く続いてきた。勤続年数に応じて給与が上がる仕組みは、社員に安心感を与え、長期的な人材育成を可能にしたと評価されている。\n　一方、成果主義を導入する企業が増えている。能力や成果を給与に直接反映させることで、社員の意欲を高め、組織を活性化させる狙いがある。ところが、短期的な成果ばかりが重視され、チームでの協力が軽んじられるという問題も指摘されている。\n　どちらの制度にも長所と短所がある以上、一方を絶対視するのは適切ではない。企業の業種や社員の価値観に合わせて、両者の長所を組み合わせた、柔軟な制度を設計していく視点が欠かせない。',
   'Di Jepang, sistem upah berdasarkan senioritas bertahan lama. Sistem yang menaikkan gaji sesuai masa kerja dinilai memberi rasa aman kepada karyawan dan memungkinkan pembinaan SDM jangka panjang.\n Di sisi lain, makin banyak perusahaan menerapkan sistem berbasis prestasi. Dengan mencerminkan kemampuan dan hasil langsung pada gaji, tujuannya menaikkan semangat karyawan dan menghidupkan organisasi. Namun ada pula masalah yang ditunjuk: hanya hasil jangka pendek yang diutamakan dan kerja sama tim terabaikan.\n Selama kedua sistem punya kelebihan dan kekurangan, tak tepat mengabsolutkan salah satu. Pandangan merancang sistem fleksibel yang menggabungkan kelebihan keduanya sesuai jenis usaha dan nilai karyawan tak terpisahkan.',
   [('年功序列の 利点と して 述べられて いる ことは 何か。', '社員に 安心感を 与え、長期的な 人材育成が できる こと', ['短期的な 成果が 上がる こと', '個人の 能力が 給与に 直結する こと', '競争が 激しく なる こと'], 'Manfaat senioritas.', '社員に安心感を与え、長期的な人材育成を可能にした'),
    ('成果主義の 問題点と して 指摘されて いる ことは 何か。', '短期的な 成果が 重視され、協力が 軽んじられる こと', ['給与が 下がる こと', '社員の 意欲が 下がる こと', '長期の 人材育成が できる こと'], 'Masalah sistem prestasi.', '短期的な成果ばかりが重視され、チームでの協力が軽んじられる'),
    ('筆者の 考えに 合う ものは どれか。', '両者の 長所を 組み合わせた 柔軟な 制度を 設計する べきだ', ['年功序列が 絶対に 優れて いる', '成果主義だけを 導入する べきだ', '給与制度は 変える べきでは ない'], 'Kalimat akhir.', '両者の長所を組み合わせた、柔軟な制度を設計')]),
 C('私たちは、日常の多くの判断を、意識せずに行っている。朝、どの道を通って駅へ向かうか、昼に何を食べるか。こうした無意識の判断は、経験に基づく「勘」として、素早く適切な決定を可能にしている。\n　だが、勘は、過去の経験に偏るという弱点を持つ。慣れた状況では有効でも、前例のない問題に対しては、かえって誤った判断を導くことがある。思い込みや先入観が、新しい情報の受け入れを妨げるからだ。\n　重要な決定を下すときには、自分の勘を信じる一方で、「この判断は経験に頼りすぎていないか」と、意識的に問い直す習慣が必要である。勘と論理的な検証を使い分けることが、賢明な判断につながる。',
   'Kita membuat banyak keputusan sehari-hari tanpa sadar. Pagi hari lewat jalan mana ke stasiun, siang makan apa. Keputusan tak sadar ini sebagai "firasat" berdasarkan pengalaman memungkinkan keputusan cepat dan tepat.\n Namun firasat punya kelemahan condong pada pengalaman masa lalu. Walau efektif di situasi akrab, untuk masalah tanpa preseden ia kadang menuntun pada keputusan keliru, karena anggapan dan prasangka menghalangi penerimaan informasi baru.\n Saat membuat keputusan penting, sambil mempercayai firasat, perlu kebiasaan menanyakan ulang secara sadar "apakah keputusan ini terlalu bergantung pada pengalaman". Memakai firasat dan verifikasi logis secara bergantian membawa pada keputusan bijak.',
   [('勘の 利点と して 述べられて いる ことは 何か。', '素早く 適切な 決定を 可能に する こと', ['新しい 情報を 受け入れやすい こと', '論理的な 検証が 不要な こと', '前例の ない 問題に 強い こと'], 'Manfaat firasat.', '素早く適切な決定を可能にしている'),
    ('勘が 誤った 判断を 導く のは どんな 場合か。', '前例の ない 問題に 直面した 場合', ['慣れた 状況の 場合', '時間が ない 場合', '他人に 相談した 場合'], 'Kapan salah.', '前例のない問題に対しては、かえって誤った判断'),
    ('筆者が 勧めて いる ことは 何か。', '勘を 信じつつ、意識的に 問い直す 習慣を 持つ こと', ['勘を 一切 信じない こと', '勘だけで 決める こと', '決定を 他人に 任せる こと'], 'Saran.', '意識的に問い直す習慣が必要')]),
 C('インターネットの普及により、専門家でなくても、誰もが情報を発信できるようになった。この「情報の民主化」は、多様な声が社会に届くという大きな利点をもたらした。\n　反面、発信される情報の質は、玉石混交である。根拠の乏しい噂や、意図的に作られた偽情報が、事実のように拡散することも珍しくない。受け手に、情報の出どころを確認し、複数の情報源と照らし合わせる習慣がなければ、誤った情報に踊らされる危険は大きい。\n　情報を発信する自由が広がった今、私たちに求められているのは、情報を鵜呑みにせず、自分の頭で吟味する力である。この力こそが、情報社会を生き抜くための最も基本的な素養だといえよう。',
   'Dengan meluasnya internet, bahkan non-pakar pun bisa menyebarkan informasi. "Demokratisasi informasi" ini membawa manfaat besar: beragam suara sampai ke masyarakat.\n Sebaliknya kualitas informasi yang tersebar campur aduk. Tak jarang gosip tanpa dasar atau informasi palsu yang sengaja dibuat menyebar seperti fakta. Bila penerima tak punya kebiasaan memeriksa sumber dan membandingkan dengan beberapa sumber, bahaya terombang-ambing informasi keliru besar.\n Kini ketika kebebasan menyebarkan informasi meluas, yang dituntut dari kita adalah kemampuan menimbang dengan kepala sendiri tanpa menelan mentah-mentah. Kemampuan inilah bekal paling mendasar untuk bertahan di masyarakat informasi.',
   [('「情報の 民主化」の 利点と して 述べられて いる ことは 何か。', '多様な 声が 社会に 届く こと', ['情報の 質が 必ず 上がる こと', '専門家が 不要に なる こと', '偽情報が なくなる こと'], 'Manfaat.', '多様な声が社会に届く'),
    ('誤った 情報に 踊らされない ために 必要な 習慣と して 挙げられて いる ものは どれか。', '情報の 出どころを 確認し、複数の 情報源と 照らし合わせる こと', ['情報を すぐ 拡散する こと', '専門家の 意見だけを 信じる こと', '情報を 見ない こと'], 'Kebiasaan.', '情報の出どころを確認し、複数の情報源と照らし合わせる'),
    ('筆者の 主張は どれか。', '情報を 鵜呑みに せず、自分で 吟味する 力が 基本的な 素養だ', ['発信の 自由を 制限する べきだ', '情報は 信頼できない ので 使うな', '専門家だけが 発信する べきだ'], 'Kalimat akhir.', '情報を鵜呑みにせず、自分の頭で吟味する力')]),
 X('<b>【A】</b><br>大学は、学生が自分の興味のままに学ぶ場であるべきだ。就職に直結しない学問でも、深く探究する経験は、物事を根本から考える力を育てる。就職活動のために学びを偏らせるのは、大学の価値を損なう。<br><br><b>【B】</b><br>大学で学んだことが、将来の仕事に生きなければ、学ぶ意味は薄い。社会が求める能力を身につけるための教育を、大学はもっと意識すべきだ。もちろん学問の自由は大切だが、卒業後の生活を考えれば、実用性を軽視することはできない。',
   '[A] Universitas seharusnya tempat mahasiswa belajar sesuai minatnya. Walau ilmu yang tak langsung terkait pekerjaan, pengalaman menyelami mendalam menumbuhkan kemampuan berpikir sampai ke akar. Mencondongkan belajar demi pencarian kerja merusak nilai universitas.\n[B] Bila yang dipelajari di universitas tak berguna bagi pekerjaan masa depan, makna belajar tipis. Universitas harus lebih menyadari pendidikan untuk menguasai kemampuan yang dibutuhkan masyarakat. Tentu kebebasan akademik penting, tetapi memikirkan hidup setelah lulus, kepraktisan tak bisa diabaikan.',
   [('大学の 役割に ついて、AとBの 考えの 違いは どれか。', 'Aは 興味に 基づく 探究を 重視し、Bは 実用性も 重視する', ['Aは 就職を 重視し、Bは 探究を 重視する', 'AもBも 実用性だけを 重視する', 'AもBも 学問の 自由を 否定する'], 'A minat; B kepraktisan.', 'A：興味のままに / B：実用性を軽視することはできない'),
    ('Bが 学問の 自由に ついて 述べて いる ことは 何か。', '大切だが、実用性を 軽視は できない', ['学問の 自由は 不要だ', '学問の 自由が 最も 重要だ', '学問の 自由は 就職に 無関係だ'], 'B mengakui kebebasan akademik tapi.', 'もちろん学問の自由は大切だが')]),
 X('<b>【A】</b><br>高齢者の運転免許の返納は、義務にするべきだ。加齢による判断力の低下は避けられず、事故が起これば、本人だけでなく他人の命も奪いかねない。公共の安全を考えれば、一定の年齢での線引きは必要である。<br><br><b>【B】</b><br>年齢だけで一律に免許を取り上げるのは、不公平だと思う。運転技能には個人差が大きく、運転が生活の足となっている地方の高齢者も多い。年齢ではなく、定期的な技能検査の結果に基づいて判断する仕組みを整えるのが現実的である。',
   '[A] Pengembalian SIM lansia sebaiknya diwajibkan. Penurunan daya nilai akibat usia tak terhindarkan dan bila kecelakaan terjadi bisa merenggut nyawa orang lain, bukan hanya diri sendiri. Memikirkan keselamatan publik, garis batas pada usia tertentu diperlukan.\n[B] Mencabut SIM secara seragam hanya berdasar usia menurut saya tak adil. Keterampilan mengemudi sangat beragam antar individu dan banyak lansia di daerah yang bergantung pada mengemudi untuk hidup. Realistis menata sistem yang menilai berdasarkan hasil uji keterampilan berkala, bukan usia.',
   [('Bが 提案して いる ことは 何か。', '定期的な 技能検査の 結果に 基づいて 判断する こと', ['年齢で 一律に 取り上げる こと', '免許を 廃止する こと', '高齢者に 運転を 勧める こと'], 'Usul B.', '定期的な技能検査の結果に基づいて判断する仕組み'),
    ('AとBの 違いは どれか。', 'Aは 年齢での 線引きを 求め、Bは 年齢だけの 判断に 反対する', ['AもBも 年齢で 判断する 考えだ', 'Aは 技能検査を 勧め、Bは 義務返納を 勧める', 'AもBも 高齢者の 運転に 反対する'], 'A garis usia; B menentang usia semata.', 'A：一定の年齢での線引き / B：年齢だけで一律に…不公平')]),
 X('<b>【A】</b><br>地方の人口減少を食い止めるには、都市から移住する人を増やすことが最も効果的だ。移住者に住宅や仕事を支援し、地方で暮らす魅力を発信すれば、人口は回復に向かう。<br><br><b>【B】</b><br>移住者を呼び込む取り組みも大切だが、それだけでは根本的な解決にならない。地元で生まれ育った若者が、仕事がないために出ていく現状を変えなければ、人口は減り続ける。地元に残りたいと思える雇用の創出が先決である。',
   '[A] Untuk menghentikan penurunan penduduk daerah, paling efektif menambah orang yang pindah dari kota. Bila mendukung pendatang dengan rumah dan pekerjaan serta menyebarkan daya tarik hidup di daerah, penduduk akan menuju pemulihan.\n[B] Upaya mengundang pendatang juga penting, tetapi itu saja bukan solusi mendasar. Bila tak mengubah kenyataan pemuda kelahiran setempat pergi karena tak ada pekerjaan, penduduk terus berkurang. Menciptakan lapangan kerja yang membuat orang ingin tinggal di daerah harus lebih dulu.',
   [('Bが 先に 行う べきだと 考えて いる ことは 何か。', '地元に 残りたいと 思える 雇用を 作る こと', ['移住者を 増やす こと', '住宅を 無料に する こと', '都市に 人を 集める こと'], 'Prioritas B.', '地元に残りたいと思える雇用の創出が先決'),
    ('AとBの 違いは どれか。', 'Aは 移住者の 増加を 重視し、Bは 地元の 若者の 流出を 防ぐ ことを 重視する', ['AもBも 移住者の 増加に 反対する', 'Aは 雇用の 創出を 重視し、Bは 移住者の 増加だけを 重視する', 'AもBも 人口減少は 問題でないと 考える'], 'A pendatang; B pemuda lokal.', 'A：移住する人を増やす / B：若者が出ていく現状を変えなければ')]),
 X('<b>【A】</b><br>職場でのメールやチャットでは、礼儀として丁寧な敬語を使うべきだ。簡略な文面は、相手に軽んじられたという印象を与えかねない。形式を守ることは、相手への敬意の表れである。<br><br><b>【B】</b><br>丁寧すぎるメールは、かえって要点が分かりにくく、やり取りの効率を下げる。特にチャットでは、簡潔さが優先されるべきだ。敬意は、言葉の長さではなく、相手の時間を大切にする姿勢で示せると思う。',
   '[A] Pada surel dan obrolan di kantor, sebaiknya gunakan keigo yang sopan sebagai tata krama. Kalimat yang singkat bisa memberi kesan lawan diremehkan. Menjaga bentuk adalah wujud hormat kepada lawan.\n[B] Surel yang terlalu sopan justru sulit dipahami pokoknya dan menurunkan efisiensi korespondensi. Terutama di obrolan, kesingkatan harus diprioritaskan. Menurut saya hormat dapat ditunjukkan bukan dengan panjang kata, tetapi dengan sikap menghargai waktu lawan.',
   [('Bが 敬意の 示し方と して 述べて いる ことは 何か。', '相手の 時間を 大切に する 姿勢', ['丁寧な 敬語を 使う こと', '長い 文面を 書く こと', '形式を 守る こと'], 'Cara hormat menurut B.', '相手の時間を大切にする姿勢'),
    ('AとBの 違いは どれか。', 'Aは 形式の 丁寧さを 重視し、Bは 簡潔さを 重視する', ['AもBも 簡潔さを 重視する', 'Aは 簡潔さを 重視し、Bは 丁寧さを 重視する', 'AもBも 敬語は 不要だと 考える'], 'A formalitas; B kesingkatan.', 'A：丁寧な敬語 / B：簡潔さが優先')]),
 X('<b>【A】</b><br>動物園は、絶滅の危機にある動物を守り、子どもたちに命の大切さを教える意義ある施設だ。野生では見られない生態を観察できる点も貴重である。<br><br><b>【B】</b><br>動物を狭い場所に閉じ込めておくことは、動物にとって大きなストレスになる。教育や保護を目的とするなら、映像技術などで代替できる部分も多い。動物園のあり方は、動物の福祉を最優先に見直されるべきだ。',
   '[A] Kebun binatang adalah fasilitas bermakna yang melindungi hewan terancam punah dan mengajari anak pentingnya kehidupan. Dapat mengamati ekologi yang tak terlihat di alam liar juga berharga.\n[B] Mengurung hewan di tempat sempit menjadi stres besar bagi hewan. Bila tujuannya pendidikan dan perlindungan, banyak bagian bisa digantikan teknologi gambar. Cara kebun binatang harus ditinjau dengan mengutamakan kesejahteraan hewan.',
   [('Bの 主張は どれか。', '動物の 福祉を 最優先に 動物園を 見直す べきだ', ['動物園を 増やす べきだ', '動物園は 教育に 不可欠だ', '動物の 数を 減らす べきだ'], 'B: kesejahteraan hewan.', '動物の福祉を最優先に見直されるべき'),
    ('Aが 動物園の 意義と して 挙げて いない ことは どれか。', '動物の ストレスを 減らす こと', ['絶滅危惧種を 守る こと', '命の 大切さを 教える こと', '野生では 見られない 生態を 観察できる こと'], 'Mengurangi stres tidak disebut A.', '絶滅の危機にある動物を守り…命の大切さ…生態を観察')]),
 T('完璧を求めるあまり、何も成し遂げられない人がいる。一方、八割の出来で一度完成させ、そこから改善を重ねる人は、結果的に質の高い成果に到達することが多い。完璧は目指すべき方向ではあっても、着手を妨げる口実にしてはならない。まず形にして、他者の目に触れさせる勇気が、成長の第一歩である。',
   'Ada orang yang karena mengejar kesempurnaan tak menyelesaikan apa pun. Sebaliknya orang yang menyelesaikan dulu dengan hasil delapan puluh persen lalu memperbaiki berulang sering akhirnya mencapai hasil berkualitas tinggi. Kesempurnaan boleh menjadi arah yang dituju, tetapi tak boleh jadi dalih menghalangi mulai. Keberanian mewujudkan dulu dan menampilkannya ke mata orang lain adalah langkah awal pertumbuhan.',
   '筆者の 主張は どれか。', '完璧を 口実に せず、まず 形に して 改善する べきだ', ['完璧に なる まで 発表しない べきだ', '八割の 出来で 満足する べきだ', '他人に 見せない べきだ'], 'Kalimat akhir.', 'まず形にして、他者の目に触れさせる勇気'),
 T('スマートフォンの普及で、私たちは常に誰かとつながっている状態にある。だが、つながりの数が増えたことと、孤独感が減ったことは別の問題である。むしろ、画面越しの浅い交流に時間を奪われ、直接顔を合わせて深く語り合う機会が減ったと感じる人も多い。つながりの量より質を問い直す時期に来ている。',
   'Dengan meluasnya ponsel, kita senantiasa dalam keadaan terhubung dengan seseorang. Namun bertambahnya jumlah hubungan dan berkurangnya rasa kesepian adalah dua masalah berbeda. Justru banyak orang merasa waktu dirampas interaksi dangkal lewat layar dan kesempatan bertatap muka berbincang mendalam berkurang. Sudah waktunya menanyakan ulang kualitas, bukan kuantitas, hubungan.',
   '筆者が 問い直す べきだと 述べて いる ことは 何か。', 'つながりの 量より 質', ['スマートフォンの 値段', '孤独感の 数値', '連絡先の 数'], 'Kalimat akhir.', 'つながりの量より質を問い直す'),
 T('文章を書くとき、難しい言葉を使えば知的に見えると考える人がいる。しかし、優れた文章とは、複雑な内容を平易な言葉で明晰に伝えるものである。読み手に負担をかける文章は、書き手が内容を十分に理解していない証拠でさえある。分かりやすさとは、読み手への最大の配慮であると心得たい。',
   'Saat menulis, ada orang yang mengira memakai kata sulit tampak cerdas. Namun tulisan yang baik adalah yang menyampaikan isi rumit dengan kata sederhana secara jernih. Tulisan yang membebani pembaca bahkan bukti penulis belum paham isinya. Ingin saya renungkan bahwa mudah dipahami adalah kepedulian terbesar kepada pembaca.',
   '筆者の 考えに 合う ものは どれか。', '分かりやすさは 読み手への 最大の 配慮だ', ['難しい 言葉を 使う ほど 優れた 文章だ', '複雑な 内容は 書く べきでは ない', '読み手は 努力して 理解する べきだ'], 'Kalimat akhir.', '分かりやすさとは、読み手への最大の配慮'),
 T('歴史を学ぶ意義は、過去の出来事を暗記することにあるのではない。過去の人々が、どのような状況で、何を考え、どう判断したのかを知ることで、現在の問題に対する見方が深まる点にある。歴史は、未来を予言するものではないが、同じ過ちを繰り返さないための、貴重な手がかりを与えてくれる。',
   'Makna belajar sejarah bukan menghafal peristiwa masa lalu. Terletak pada pandangan terhadap masalah masa kini yang mendalam dengan mengetahui dalam situasi apa orang masa lalu berpikir apa dan memutuskan bagaimana. Sejarah bukan meramal masa depan, tetapi memberi petunjuk berharga agar tak mengulang kesalahan yang sama.',
   '筆者は 歴史を 学ぶ 意義を どう 述べて いるか。', '現在の 問題への 見方が 深まり、過ちを 繰り返さない 手がかりに なる', ['過去の 出来事を 暗記する こと', '未来を 正確に 予言できる こと', '昔の 人を 批判する こと'], 'Makna belajar sejarah.', '現在の問題に対する見方が深まる…過ちを繰り返さないための手がかり'),
 T('SNSで「いいね」の数を気にしすぎる人が増えている。他人の評価が自分の価値を決めるかのように感じてしまうためだ。しかし、数字に表れる評価は、その人の一側面にすぎない。評価を完全に無視する必要はないが、自分が何を大切にしたいのかという軸を持つことが、他人の評価に振り回されないための支えとなる。',
   'Makin banyak orang terlalu memikirkan jumlah "suka" di media sosial karena merasa penilaian orang lain menentukan nilai dirinya. Namun penilaian yang tampak dalam angka hanya satu sisi orang itu. Tak perlu mengabaikan penilaian sepenuhnya, tetapi memiliki poros tentang apa yang ingin dihargai adalah penopang agar tak terombang-ambing penilaian orang lain.',
   '筆者の 考えに 合う ものは どれか。', '自分が 大切に したい 軸を 持つ ことが 支えに なる', ['評価は すべて 無視する べきだ', '数字の 評価が 自分の 価値だ', 'SNSは やめる べきだ'], 'Kalimat akhir.', '自分が何を大切にしたいのかという軸を持つこと'),
]
